#include <iostream>
using namespace std;
struct Base {
    virtual void f() { cout << "Bf "; }
    void g() { cout << "Bg "; f(); }
};
struct Der : Base {
    void f() override { cout << "Df "; }
    void g() { cout << "Dg "; }
};
int main() {
    Der d; Base *p = &d; Base b = d;
    p->g(); p->Base::f(); b.f(); d.g();
}

#include <iostream>
using namespace std;
struct Part { ~Part() { cout << "~Part "; } };
struct Machine {
    Machine() { cout << "M:" << name() << " "; }
    virtual ~Machine() { cout << "~M:" << name() << " "; }
    virtual const char *name() const { return "machine"; }
};
struct Robot : Machine {
    Part arm;
    Robot() { cout << "R:" << name() << " "; }
    ~Robot() { cout << "~R "; }
    const char *name() const override { return "robot"; }
};
int main() { Machine *m = new Robot; delete m; }

